/* 聚合逻辑示意：实际在Python里做 */
SELECT b.business_id, b.name, b.review_count
FROM business b
JOIN review r ON b.business_id=r.business_id
WHERE r.review_id IN (...semantic_hits_in_tampa...);

SELECT review_id, business_id, user_id, stars, date, text
FROM review
